// LLVM instcombine - optimization pass demo (constant folding)
function fold(node) {
  if (node.op === "add" && typeof node.l === "number" && typeof node.r === "number")
    return { op: "const", v: node.l + node.r };
  return node;
}
var before = { op: "add", l: 20, r: 22 };
var after = fold(before);
console.log("Pass: instcombine | Runs on: LLVM IR");
console.log("Before: " + JSON.stringify(before));
console.log("After:  " + JSON.stringify(after));
console.log("Constant folded at compile time -> PASS");

